     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        if (request.children() < 0) {
    35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the number of children cannot be negative");
    36	        }
    37	        Room room = rooms.find(request.roomNumber())
    38	                .orElseThrow(() -> new HotelException(
    39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    40	        if (request.guests() + request.children() > room.capacity()) {
    41	            throw new HotelException(
    42	                    ErrorCode.CAPACITY_EXCEEDED,
    43	                    "room " + room.number() + " takes at most " + room.capacity() + " guests, children included");
    44	        }
    45	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    46	            throw new HotelException(
    47	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    48	        }
    49	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    50	        return store.add(request, price);
    51	    }
    52	
    53	    public Reservation find(long reservationId) {
    54	        return store.find(reservationId)
    55	                .orElseThrow(() -> new HotelException(
    56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    57	    }
    58	
    59	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    60	    public synchronized Reservation confirm(long reservationId) {
    61	        Reservation reservation = find(reservationId);
    62	        if (reservation.status() != ReservationStatus.PENDING) {
    63	            throw notAllowed(reservation, "confirm");
    64	        }
    65	        reservation.confirmPayment();
    66	        store.update(reservation);
    67	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    68	        emailSender.send(
    69	                reservation.guest().email(),
    70	                "Reserva confirmada - " + HOTEL_NAME,
    71	                confirmationEmailBody(reservation, receipt));
    72	        return reservation;
    73	    }
    74	
    75	    /**
    76	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    77	     * reservation was never paid, so nothing comes back).
    78	     */
    79	    public synchronized Reservation cancel(long reservationId) {
    80	        Reservation reservation = find(reservationId);
    81	        if (reservation.status() != ReservationStatus.PENDING
    82	                && reservation.status() != ReservationStatus.CONFIRMED) {
    83	            throw notAllowed(reservation, "cancel");
    84	        }
    85	        BigDecimal refund = switch (reservation.ratePlan()) {
    86	            case STANDARD -> reservation.amountPaid();
    87	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    88	        };
    89	        reservation.cancel(refund);
    90	        store.update(reservation);
    91	        return reservation;
    92	    }
    93	
    94	    public synchronized Reservation checkIn(long reservationId) {
    95	        Reservation reservation = find(reservationId);
    96	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    97	            throw notAllowed(reservation, "check in");
    98	        }
    99	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
