     8	
     9	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
    10	public record ReservationReceipt(
    11	        String title,
    12	        long reservationId,
    13	        String guestName,
    14	        String guestCpf,
    15	        int roomNumber,
    16	        RoomType roomType,
    17	        int children,
    18	        LocalDate checkIn,
    19	        LocalDate checkOut,
    20	        int nights,
    21	        BigDecimal subtotal,
    22	        BigDecimal discount,
    23	        BigDecimal total) {
    24	
    25	    public ReservationReceipt(Reservation reservation, Room room) {
    26	        this(
    27	                "Comprovante de reserva",
    28	                reservation.id(),
    29	                reservation.guest().name(),
    30	                reservation.guest().cpf(),
    31	                room.number(),
    32	                room.type(),
    33	                reservation.children(),
    34	                reservation.checkIn(),
    35	                reservation.checkOut(),
    36	                reservation.price().nights(),
    37	                reservation.price().subtotal(),
    38	                reservation.price().discount(),
    39	                reservation.price().total());
    40	    }
    41	
    42	    public String text() {
    43	        StringBuilder text = new StringBuilder();
    44	        text.append(title).append(" nº ").append(reservationId).append('\n');
    45	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    46	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    47	        if (children > 0) {
    48	            text.append("Crianças: ").append(children).append('\n');
    49	        }
    50	        text.append("Entrada: ").append(TextFormat.date(checkIn))
    51	                .append(" | Saída: ").append(TextFormat.date(checkOut))
    52	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    53	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
    54	        if (discount.signum() > 0) {
    55	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
    56	        }
    57	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
    58	        return text.toString();
    59	    }
    60	}
